SELECT c.id, c.student_id, s.name as student_name, c.coach_id, co.name as coach_name, c.start_time, c.end_time, TIMESTAMPDIFF(MINUTE, c.start_time, c.end_time) as duration, c.price, c.status, c.table_number, c.create_time FROM course c LEFT JOIN user s ON c.student_id = s.id LEFT JOIN user co ON c.coach_id = co.id WHERE (c.student_id = #{userId} OR c.coach_id = #{userId}) AND c.deleted = 0
AND c.status = #{queryDTO.status}
AND DATE(c.start_time) >= #{queryDTO.startDate}
AND DATE(c.start_time) <= #{queryDTO.endDate}
ORDER BY c.start_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM course c
WHERE (c.student_id = #{userId} OR c.coach_id = #{userId})
AND c.deleted = 0

    AND c.status = #{queryDTO.status}


    AND DATE(c.start_time) >= #{queryDTO.startDate}


    AND DATE(c.start_time) <= #{queryDTO.endDate}

SELECT COUNT(1) > 0
FROM course
WHERE coach_id = #{coachId}
AND deleted = 0
AND status IN ('pending', 'confirmed')
AND (
(start_time < #{endTime} AND end_time > #{startTime})
)

    AND id != #{excludeCourseId}



SELECT #{date} + INTERVAL hour HOUR as available_time
FROM (
SELECT 9 as hour UNION SELECT 10 UNION SELECT 11 UNION SELECT 14
UNION SELECT 15 UNION SELECT 16 UNION SELECT 17 UNION SELECT 18
) hours
WHERE NOT EXISTS (
SELECT 1 FROM course
WHERE coach_id = #{coachId}
AND DATE(start_time) = #{date}
AND HOUR(start_time) = hour
AND deleted = 0
AND status IN ('pending', 'confirmed')
)
